import { ChangeDetectionStrategy, Component, input } from '@angular/core';

export type AevkoKbdSize = 'sm' | 'md';

@Component({
  selector: 'kbd[aevkoKbd]',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './kbd.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'kbd', '[attr.data-size]': 'size()' },
})
export class AevkoKbd {
  readonly size = input<AevkoKbdSize>('md');
}

:host {
  align-items: center;
  background: var(--aevko-surface, #f4f4f5);
  border: 1px solid var(--aevko-border, #d4d4d8);
  border-radius: var(--aevko-radius, 0);
  color: var(--aevko-foreground, #18181b);
  display: inline-flex;
  font: 600 0.75rem/1 var(--aevko-font-mono, ui-monospace, monospace);
  justify-content: center;
  min-block-size: 1.5rem;
  min-inline-size: 1.5rem;
  padding-inline: 0.375rem;
  white-space: nowrap;
}

:host([data-size='sm']) {
  font-size: 0.6875rem;
  min-block-size: 1.25rem;
  min-inline-size: 1.25rem;
  padding-inline: 0.25rem;
}

import { ChangeDetectionStrategy, Component } from '@angular/core';

@Component({
  selector: 'span[aevkoKbdGroup]',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './kbd-group.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'kbd-group' },
})
export class AevkoKbdGroup {}

:host {
  align-items: center;
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}
